def has_1pos_and_kwonly(func):
    """Check if function has exactly 1 positional argument and keyword-only arguments."""
    if PY2:
        # Python 2 doesn't have keyword-only args
        return False
    spec = inspect.signature(func)
    params = list(spec.parameters.values())
    if len(params) < 1:
        return False
    # Check first param is positional-or-keyword or positional-only
    first_param = params[0]
    if first_param.kind in (first_param.VAR_POSITIONAL, first_param.VAR_KEYWORD):
        return False
    # Check if there are keyword-only parameters
    has_kwonly = any(p.kind == p.KEYWORD_ONLY for p in params[1:])
    return has_kwonly

